/* Types */
/**  Who may reach a protected route: any of these emails, or anyone at these domains. */
export type AccessRule = {
	/**  Email addresses, e.g. `me@xyz.com`. */
	emails: string[],
	/**  Email domains, e.g. `xyz.com`. */
	emailDomains: string[],
};

/**  A connected Cloudflare account. */
export type Account = {
	/**  Cloudflare account id. */
	id: string,
	/**  Display name. */
	name: string,
	/**  How it was connected. */
	credential: CredentialKind,
	/**  For cert.pem credentials: the only zone the credential works for. */
	limitedZone: string | null,
};

/**  One entry of the activity log. */
export type ActivityEntry = {
	/**  Row id. */
	id: number,
	/**  Milliseconds since the epoch. */
	at: number | null,
	/**  What was asked, e.g. "Add app.xyz.com → http://localhost:3000". */
	summary: string,
	/**  `applied`, `rolledBack` or `partiallyApplied`. */
	outcome: string,
	/**
	 *  Step descriptions and any error, as plain lines (search, and entries from
	 *  before the structured record).
	 */
	detail: string[],
	/**  Kind, hostnames, step states and before/after (absent in older entries). */
	record: ActivityRecord | null,
};

/**  What kind of change an entry records (for filtering). */
export type ActivityKind = 
/**  A route was added. */
"addRoute" | 
/**  A route was changed or renamed. */
"updateRoute" | 
/**  A route was removed. */
"removeRoute" | 
/**  Every route was removed and the tunnel deleted. */
"removeTunnel" | 
/**  Routes were imported from a cloudflared setup. */
"importRoutes" | 
/**  A DNS record was deleted (Doctor cleanup). */
"deleteRecord" | 
/**  Routes were restored after an outside edit. */
"restoreConfig" | 
/**  A login whose route was gone was removed (Doctor cleanup). */
"removeLogin" | 
/**  A private network was shared. */
"addNetwork" | 
/**  A private network stopped being shared. */
"removeNetwork" | 
/**  Another tunnel was created for this Mac. */
"createTunnel" | 
/**  A route started being load balanced. */
"balanceRoute" | 
/**  A route stopped being load balanced. */
"unbalanceRoute";

/**  The structured part of an activity entry. */
export type ActivityRecord = {
	/**  What kind of change. */
	kind: ActivityKind,
	/**  Every hostname involved, sorted. */
	hostnames: string[],
	/**  The tunnel's name. */
	tunnel: string,
	/**  The steps that change something, in order. */
	steps: RecordedStep[],
	/**  What changed, routes first. */
	changes: Delta[],
	/**  What was asked (absent in entries from before messages had keys). */
	summary?: Text | null,
	/**  Why it failed, when it did. */
	error?: Text | null,
	/**  What couldn't be undone after a failure. */
	leftovers?: Text[],
	/**  The routes were applied but this Mac's connector couldn't be started. */
	connectorError?: Text | null,
};

/**  Whether this Mac's connector can run as a service, and whether it does. */
export type AlwaysOn = {
	/**  This system supports Always-on. */
	supported: boolean,
	/**  The connector runs as a service. */
	enabled: boolean,
};

/**
 *  An error as shown to the user: what happened, and what to do about it. The text is
 *  translated by the UI (D-062).
 */
export type AppError = {
	/**  Category for programmatic handling. */
	code: ErrorCode,
	/**  One sentence describing what happened. */
	message: Text,
	/**
	 *  What the user can do about it (boxed: most errors have none, and a small error
	 *  keeps every command's `Result` small).
	 */
	hint: Text | null,
	/**  The input field the error refers to. */
	field: string | null,
};

/**  Static facts about the running app. */
export type AppInfo = {
	/**  App version (semver). */
	version: string,
	/**  Operating system: `macos`, `linux` or `windows`. */
	platform: string,
	/**  CPU architecture, e.g. `aarch64`. */
	arch: string,
	/**  Directory holding the database, logs and managed binaries. */
	dataDir: string,
};

/**  A message argument: a number (formatted for the language) or text. */
export type Arg = 
/**  A number, e.g. a count (a JavaScript number in the UI). */
number | null | 
/**  Anything else, already as text (hostnames, names, versions). */
string;

/**  Where cloudflared comes from and whether it's new enough. */
export type BinaryInfo = {
	/**  Absolute path. */
	path: string,
	/**  `managed`, `system` or `override`. */
	source: string,
	/**  Version, if readable. */
	version: string | null,
	/**  Whether it supports everything Teitunnel needs. */
	supported: boolean,
};

/**  Everything a credential can do in one account. */
export type Capabilities = {
	/**  List domains. */
	zonesRead: Grant,
	/**  List tunnels. */
	tunnelsRead: Grant,
	/**  Create and configure tunnels. */
	tunnelsEdit: Grant,
	/**  Access policies (optional feature). */
	accessEdit: Grant,
	/**  DNS editing, per domain. */
	zones: ZoneGrant[],
};

/**  A change the user asks for (or a Doctor fix proposes). */
export type Change = 
/**  Add a route. */
{ type: "addRoute"; 
/**  The route. */
route: RouteInput } | 
/**  Edit or rename a route. */
{ type: "updateRoute"; 
/**  Current hostname. */
hostname: string; 
/**  Current path. */
path: string | null; 
/**  The new definition. */
route: RouteInput } | 
/**  Remove a route. */
{ type: "removeRoute"; 
/**  Hostname. */
hostname: string; 
/**  Path. */
path: string | null } | 
/**  Remove every route and delete this Mac's tunnel. */
{ type: "removeTunnel" } | 
/**  Load balance a route across the tunnels that route its hostname. */
{ type: "balanceRoute"; 
/**  Hostname. */
hostname: string } | 
/**  Stop load balancing a route. */
{ type: "unbalanceRoute"; 
/**  Hostname. */
hostname: string } | 
/**  Create another tunnel for this Mac. */
{ type: "createTunnel"; 
/**  Its name. */
name: string } | 
/**  Undo an outside edit of this Mac's routes. */
{ type: "restoreConfig" } | 
/**  Remove a login Teitunnel added whose route is gone. */
{ type: "removeLogin"; 
/**  The Access domain, e.g. `app.example.com` or `app.example.com/admin`. */
domain: string } | 
/**  Add several routes at once (import from an existing cloudflared setup). */
{ type: "importRoutes"; 
/**  The routes. */
routes: RouteInput[] } | 
/**  Let WARP clients reach a private range through this Mac's tunnel. */
{ type: "addNetwork"; 
/**  An IP address or CIDR range, e.g. `192.168.1.0/24`. */
network: string } | 
/**  Stop sharing a private range. */
{ type: "removeNetwork"; 
/**  The range. */
network: string } | 
/**  Delete one DNS record (an orphan found by the Doctor). */
{ type: "deleteRecord"; 
/**  Zone id. */
zoneId: string; 
/**  The record's name. */
hostname: string; 
/**  Record id. */
recordId: string };

/**  A terminal's live Quick Share. */
export type CliShare = {
	/**  The CLI process (`<pid>-<start time>`). */
	owner: string,
	/**  What's shared. */
	origin: string,
	/**  Its public URL. */
	url: string,
	/**  When it started (milliseconds since the epoch). */
	startedAt: number | null,
	/**  When it stops by itself (milliseconds since the epoch). */
	stopAt: number | null,
};

/**  What a visitor runs to reach a non-HTTP route. */
export type ClientAccess = {
	/**  The protocol. */
	protocol: ClientProtocol,
	/**  The command to run (SSH: to connect; others: to open the local port). */
	command: string,
	/**  Where the visitor's app connects once the command runs (`None` for SSH). */
	localAddress: string | null,
	/**  An `~/.ssh/config` entry, so plain `ssh <hostname>` works (SSH only). */
	sshConfig: string | null,
};

/**  The protocol a non-HTTP route carries. */
export type ClientProtocol = 
/**  SSH. */
"ssh" | 
/**  Remote Desktop. */
"rdp" | 
/**  Windows file sharing. */
"smb" | 
/**  Any TCP service (a database, …). */
"tcp";

/**  One edge connection of a connector. */
export type ConnectionView = {
	/**  Edge location, e.g. `ams01`. */
	colo: string,
	/**  When it connected (RFC 3339). */
	openedAt: string,
};

/**  Lifecycle of one connector (ARCHITECTURE §5.1). */
export type ConnectorState = 
/**  Not running. */
{ state: "stopped" } | 
/**  The process is being spawned. */
{ state: "starting" } | 
/**  Running, but no edge connection yet. */
{ state: "connecting" } | 
/**  Serving traffic. */
{ state: "healthy"; 
/**  Registered edge connections. */
connections: number } | 
/**
 *  Running with no edge connections after having had some (or after the start
 *  timeout).
 */
{ state: "degraded" } | 
/**  Exited unexpectedly; restarts after a backoff. */
{ state: "crashed"; 
/**  Restart attempt number (1-based). */
attempt: number; 
/**  Milliseconds until the restart. */
retry_in_ms: number; 
/**  Exit code, when there was one. */
exit_code: number | null } | 
/**  Crashed too often in a short time; not restarted automatically. */
{ state: "crashLoop"; 
/**  Exit code of the last crash. */
exit_code: number | null } | 
/**  Shutting down. */
{ state: "stopping" };

/**  One machine running a tunnel (a cloudflared process), with its edge connections. */
export type ConnectorView = {
	/**  Connector id. */
	id: string,
	/**  cloudflared version. */
	version: string,
	/**  Public IP it connects from. */
	originIp: string,
	/**  It's this Mac's connector. */
	thisMac: boolean,
	/**  Edge connections, by location. */
	connections: ConnectionView[],
};

/**  How an account was connected. */
export type CredentialKind = 
/**  A user API token. */
"apiToken" | 
/**  OAuth sign-in (refresh token in the keychain). */
"oauth" | 
/**  Imported from `cloudflared tunnel login` (cert.pem); one zone only. */
"certPem";

/**  One thing that changed: absent `before` means added, absent `after` removed. */
export type Delta = {
	/**  Route or DNS record. */
	area: DeltaArea,
	/**  Public hostname. */
	hostname: string,
	/**  Path rule, for routes that have one. */
	path: string | null,
	/**  What it was. */
	before: Text | null,
	/**  What it became. */
	after: Text | null,
};

/**  Where a change happened. */
export type DeltaArea = 
/**  The tunnel's routes (ingress). */
"route" | 
/**  A DNS record. */
"dns" | 
/**  A private network route. */
"network" | 
/**  A route's login (Cloudflare Access). */
"access" | 
/**  A route's load balancing. */
"loadBalancing";

/**  Whether a route's DNS record points at this Mac's tunnel. */
export type DnsState = 
/**  A proxied CNAME to the tunnel. */
{ state: "ok" } | 
/**  No record. */
{ state: "missing" } | 
/**  A record pointing somewhere else (or not proxied). */
{ state: "elsewhere"; 
/**  What it points at. */
content: string };

/**  A domain in a connected account. */
export type Domain = {
	/**  Zone id. */
	id: string,
	/**  Domain name. */
	name: string,
	/**  Setup state. */
	status: DomainStatus,
	/**  Cloudflare nameservers to set at the registrar. */
	nameServers: string[],
	/**  Nameservers currently at the registrar (before the switch). */
	originalNameServers: string[],
	/**  Plan name. */
	plan: string | null,
	/**  Whether the proxy is paused. */
	paused: boolean,
};

/**  A temporary route, as remembered. */
export type DomainShare = {
	/**  Account id. */
	accountId: string,
	/**  The public hostname. */
	hostname: string,
	/**  The service shared, as the user gave it. */
	origin: string,
	/**  [`APP_OWNER`], or the CLI process that started it. */
	owner: string,
	/**  When it ends by itself (milliseconds since the epoch). */
	expiresAt: number | null,
	/**  When it started (milliseconds since the epoch). */
	createdAt: number | null,
};

/**  Where a domain is in its setup. */
export type DomainStatus = 
/**  Active on Cloudflare: routes can use it. */
"active" | 
/**  Waiting for the registrar to switch nameservers. */
"pending" | 
/**  Nameservers moved away from Cloudflare. */
"moved" | 
/**  Being set up, or a state we don't know. */
"other";

/**  An outside edit of this Mac's tunnel configuration. */
export type Drift = {
	/**  Tunnel id. */
	tunnelId: string,
	/**  Version Teitunnel last wrote. */
	appliedVersion: number,
	/**  Version now. */
	currentVersion: number,
	/**  Routes that differ. */
	changes: RuleChange[],
};

/**  Emitted after anything changes, so the UI can invalidate the affected queries. */
export type EntityChanged = {
	/**  What kind of entity changed. */
	kind: EntityKind,
	/**  Which one, when a single entity changed. */
	id: string | null,
};

/**  Kinds of entities the UI caches. Each maps to TanStack Query keys on the frontend. */
export type EntityKind = 
/**  App settings. */
"settings" | 
/**  Quick Shares (list, status, URL). */
"quickShares" | 
/**  Connected Cloudflare accounts (and their domains). */
"accounts" | 
/**  Routes and this Mac's tunnel (id: the account). */
"routes";

/**  Machine-readable error category. The frontend branches on this, never on `message`. */
export type ErrorCode = 
/**  An unexpected failure. The message is safe to show; details are in the app log. */
"internal" | 
/**  The input was rejected; `field` names the offending field. */
"invalidInput" | 
/**  The thing acted on doesn't exist (any more). */
"notFound" | 
/**  cloudflared isn't installed. */
"cloudflaredMissing" | 
/**  Busy or exhausted; retrying later may work. */
"unavailable" | 
/**
 *  Something changed since the user looked, or a confirmation is missing: refresh
 *  the preview.
 */
"conflict" | 
/**  The Cloudflare credential lacks a permission. */
"permissionDenied";

/**  A rendered export. */
export type ExportFile = {
	/**  Suggested file name, e.g. `config.yml`. */
	fileName: string,
	/**  The file. */
	contents: string,
};

/**  What to export as. */
export type ExportFormat = 
/**  A cloudflared `config.yml` (ingress rules). */
"configYaml" | 
/**  A Docker Compose service running the tunnel. */
"dockerCompose" | 
/**  Terraform for the Cloudflare provider v5, with `import` blocks. */
"terraform";

/**  Why a route doesn't work. */
export type Failure = 
/**  There's no DNS record for the hostname. */
{ type: "noRecord" } | 
/**  The record exists but doesn't point at this Mac's tunnel (or isn't proxied). */
{ type: "recordElsewhere"; 
/**  What it points at. */
content: string } | 
/**  The edge couldn't be reached (network, firewall). */
{ type: "edgeUnreachable"; 
/**  The error. */
message: string } | 
/**  The certificate doesn't cover the hostname (Universal SSL covers one level). */
{ type: "certificateNotCovered" } | 
/**  Cloudflare doesn't know the hostname yet (error 1001), usually propagation. */
{ type: "notOnCloudflareYet" } | 
/**  No connector is connected to the tunnel (error 1033). */
{ type: "noConnector" } | 
/**  The record points at a tunnel that doesn't serve it (error 1016 / 530). */
{ type: "tunnelMismatch" } | 
/**  The connector couldn't reach the origin (502). */
{ type: "originUnreachable"; 
/**  Whether something listens on the origin's local port (None: not local). */
listening: boolean | null } | 
/**  The origin didn't answer in time (504). */
{ type: "originTimeout" };

/**  What the preview shows for a file. */
export type FileSummary = {
	/**  Path inside the archive. */
	name: string,
	/**  Size in bytes. */
	size: number,
	/**  The first lines, for a quick look. */
	excerpt: string,
};

/**  A way to fix an issue. */
export type Fix = 
/**  A change in Cloudflare, previewed as a plan before it's applied. */
{ type: "change"; 
/**  Button title, e.g. "Fix the DNS Record". */
label: Text; 
/**  The change. */
change: Change } | 
/**  Install (or update) the managed cloudflared. */
{ type: "installBinary" } | 
/**  Start this Mac's connector. */
{ type: "startConnector"; 
/**  Account. */
accountId: string } | 
/**  Accept an outside edit of this Mac's routes. */
{ type: "keepTheirs"; 
/**  Account. */
accountId: string } | 
/**  Create a token with the right permissions. */
{ type: "reconnect" } | 
/**  Remove a tunnel's stale connections. */
{ type: "cleanConnections"; 
/**  Account. */
accountId: string; 
/**  Tunnel. */
tunnelId: string };

/**  What "Fix all safe issues" did. */
export type FixReport = {
	/**  Issues fixed. */
	fixed: number,
	/**  Issues left for the user (their fix needs a confirmation or a decision). */
	skipped: number,
	/**  Fixes that failed (and were rolled back), with why. */
	failed: string[],
};

/**  A cloudflared process Teitunnel doesn't manage. */
export type ForeignConnector = {
	/**  Process id. */
	pid: number,
	/**  The command line, with tokens replaced by `[redacted]`. */
	command: string,
	/**  What it's doing. */
	mode: ForeignMode,
	/**  Started by launchd (a service) rather than a terminal. */
	service: boolean,
	/**  Its metrics address, when it has one. */
	metrics: string | null,
	/**  Edge connections reported by `/ready` (None: no metrics server answered). */
	connections: number | null,
};

/**  What a foreign cloudflared is doing. */
export type ForeignMode = 
/**  `tunnel --url …`: a Quick Tunnel. */
{ type: "quickTunnel"; 
/**  The local origin. */
origin: string } | 
/**  `tunnel run [name]`, with a token or a config. */
{ type: "named"; 
/**  The tunnel name or id, when given on the command line. */
tunnel: string | null; 
/**  The config file, when given. */
config: string | null } | 
/**  Something else (`access`, `proxy-dns`, …). */
{ type: "other" };

/**  One route found in a config file. */
export type FoundRoute = {
	/**  Hostname. */
	hostname: string,
	/**  Path regex. */
	path: string | null,
	/**  Service, e.g. `http://localhost:3000`. */
	service: string,
	/**  Why it can't be imported, if it can't. */
	unsupported: Text | null,
};

/**  The result of probing one permission. */
export type Grant = 
/**  Allowed. */
"yes" | 
/**  Not allowed. */
"no" | 
/**  Couldn't be checked right now. */
"unknown";

/**  A page of help on the web. */
export type HelpLink = 
/**  Teitunnel's documentation. */
"docs" | 
/**  Cloudflare Tunnel's documentation. */
"cloudflareDocs" | 
/**  Release notes. */
"releaseNotes" | 
/**  Report an issue. */
"reportIssue";

/**  A span of persisted history. */
export type HistoryRange = 
/**  The last 24 hours, in 5-minute buckets. */
"day" | 
/**  The last 7 days, in 30-minute buckets. */
"week";

/**  Install progress, streamed to the webview. */
export type InstallProgress = 
/**  Downloading: bytes received of total. */
{ step: "downloading"; 
/**  Bytes received. */
received: number; 
/**  Total bytes. */
total: number } | 
/**  Checking checksums and the code signature. */
{ step: "verifying" } | 
/**  Moving the binary into place. */
{ step: "installing" };

/**  A detected problem. */
export type Issue = {
	/**  Stable id (check, account, subject), so "Ignore" survives restarts. */
	id: string,
	/**  Which check found it, e.g. `dns.missing`. */
	check: string,
	/**  How bad it is. */
	severity: Severity,
	/**  The account it's in, if any. */
	accountId: string | null,
	/**  What it's about, e.g. a hostname or a tunnel name (stable: part of `id`). */
	subject: string,
	/**  `subject` as shown to the user. */
	label: Text,
	/**  One line. */
	title: Text,
	/**  What it means and what to do. */
	detail: Text,
	/**  Supporting facts (records, states). */
	evidence: Text[],
	/**  Fixes, the recommended one first. */
	fixes: Fix[],
	/**  The tunnel of this Mac's it's about, when not the default one (a fix applies there). */
	tunnelId: string | null,
};

/**  A TCP port something on this machine is listening on. */
export type LocalService = {
	/**  The port. */
	port: number,
	/**  Whether it listens on all interfaces (vs. loopback only). */
	allInterfaces: boolean,
	/**  Owning process id. */
	pid: number,
	/**  Process name, e.g. `node`. */
	process: string,
	/**  What it looks like, e.g. a Vite dev server. */
	kind: ServiceKind,
	/**  Project the process runs in (from its working directory), e.g. `my-app`. */
	project: string | null,
	/**  Suggested origin URL, e.g. `http://localhost:5173`. */
	origin: string,
};

/**  A cloudflared configuration found on disk. */
export type LocalSetup = {
	/**  The config file. */
	configPath: string,
	/**  `tunnel:` (a UUID or a name). */
	tunnel: string | null,
	/**  The Cloudflare account the credentials belong to. */
	accountId: string | null,
	/**  The tunnel id from the credentials file. */
	tunnelId: string | null,
	/**  Routes (hostname rules) in order. */
	routes: FoundRoute[],
	/**
	 *  Settings that apply to every route (`originRequest`), which Teitunnel can't
	 *  carry over per route yet.
	 */
	hasGlobalOptions: boolean,
	/**  Problems reading the file. */
	problem: Text | null,
};

/**  One cloudflared log line, for the log drawer. */
export type LogLine = {
	/**  Timestamp as printed by cloudflared. */
	time: string | null,
	/**  `debug`, `info`, `warn`, `error`, `fatal` or `raw`. */
	level: string,
	/**  The message. */
	message: string,
	/**  The `error` field, if any. */
	error: string | null,
};

/**  Emitted when a menu-bar item that the webview handles is chosen. */
export type MenuAction = {
	/**  The chosen command. */
	command: MenuCommand,
};

/**  A menu-bar command the webview handles (navigation, panes, palette). */
export type MenuCommand = 
/**  File ▸ New Route (⌘N). */
"newRoute" | 
/**  File ▸ New Quick Share (⇧⌘N). */
"newQuickShare" | 
/**  View ▸ Toggle Sidebar (⌥⌘S). */
"toggleSidebar" | 
/**  View ▸ Toggle Inspector (⌥⌘I). */
"toggleInspector" | 
/**  View ▸ Refresh (⌘R). */
"refresh" | 
/**  View ▸ Command Palette (⌘K). */
"commandPalette" | 
/**  View ▸ Overview (⌘1). */
"goOverview" | 
/**  View ▸ Routes (⌘2). */
"goRoutes" | 
/**  View ▸ Quick Share (⌘3). */
"goQuickShare" | 
/**  View ▸ Domains (⌘4). */
"goDomains" | 
/**  View ▸ Tunnels (⌘5). */
"goTunnels" | 
/**  View ▸ Activity (⌘6). */
"goActivity" | 
/**  View ▸ Doctor (⌘7). */
"goDoctor" | 
/**  Quit was chosen while routes run through the app: ask what to do. */
"confirmQuit" | 
/**  Help ▸ Export Diagnostics… */
"exportDiagnostics";

/**  A private network shared through this Mac's tunnel. */
export type NetworkView = {
	/**  The range, e.g. `192.168.1.0/24`. */
	network: string,
	/**
	 *  In private address space (a public range takes those addresses over for WARP
	 *  clients).
	 */
	private: boolean,
	/**  Teitunnel added it (otherwise it was added in the dashboard or with cloudflared). */
	owned: boolean,
};

/**
 *  An HTTP(S) origin cloudflared can proxy to, e.g. `http://localhost:3000`.
 * 
 *  Parsing is forgiving about what people type: `3000`, `:3000`, `localhost:3000`,
 *  `127.0.0.1:8080` and full URLs all work. Paths and query strings are dropped;
 *  cloudflared proxies the whole host.
 */
export type OriginUrl = string;

/**  How applying ended. */
export type Outcome = 
/**  Every step succeeded. */
{ type: "applied"; 
/**  This Mac's tunnel afterwards (None once deleted). */
tunnelId: string | null; 
/**  Hostnames to verify next. */
verify: string[]; 
/**  The connector couldn't be started (the routes are configured, though). */
connectorError: Text | null } | 
/**  A step failed and everything done before it was undone. */
{ type: "rolledBack"; 
/**  Index of the failed step. */
failedStep: number; 
/**  Why it failed. */
error: Text } | 
/**  A step failed and some earlier changes couldn't be undone. */
{ type: "partiallyApplied"; 
/**  Index of the failed step. */
failedStep: number; 
/**  Why it failed. */
error: Text; 
/**  What was left in place. */
leftovers: Text[] };

/**  A plan, as shown in the preview. */
export type PlanView = {
	/**  Steps in order (empty: nothing to change). */
	steps: StepView[],
	/**  Things to review. */
	warnings: Warning[],
	/**  Confirmation needed (touches records Teitunnel didn't create). */
	requiresConfirmation: boolean,
	/**  Pass back to apply, so a change made meanwhile is caught. */
	fingerprint: string,
};

/**  A progress update for the step at `step` (index into the plan). */
export type Progress = {
	/**  Step index. */
	step: number,
	/**  Its state. */
	state: StepState,
};

/**  A running Quick Share, as the UI sees it. */
export type QuickShare = {
	/**  Identifier. */
	id: string,
	/**  The local service being shared. */
	origin: OriginUrl,
	/**  The public URL, once cloudflared has one. */
	url: string | null,
	/**  Current status. */
	status: ShareStatus,
	/**
	 *  Start time, milliseconds since the Unix epoch.
	 * 
	 *  Exported to TypeScript as `number` (values stay far below 2^53). The `u32` is
	 *  only a type hint for specta, which exports `u64` as bigint and `f64` as nullable.
	 */
	startedAt: number,
	/**  When it stops by itself, milliseconds since the Unix epoch. */
	stopAt: number | null,
};

/**  A step of the applied plan and how it ended. */
export type RecordedStep = {
	/**  The step as previewed (with its command). */
	step: StepView,
	/**  Its final state. */
	state: StepState,
};

/**  Where a session is. */
export type RemoteLogState = 
/**  Getting a token and connecting. */
{ state: "connecting" } | 
/**  Receiving the connector's logs. */
{ state: "streaming" } | 
/**  Stopped for good; stop the session and read again to retry. */
{ state: "ended"; 
/**  Why, in a sentence. */
message: Text };

/**  A connector's live logs, when it runs on another machine. */
export type RemoteLogsView = {
	/**  Where the stream is. */
	state: RemoteLogState,
	/**  The newest lines, oldest first. */
	lines: LogLine[],
};

/**  A route as typed in the add/edit sheet. */
export type RouteInput = {
	/**  Public hostname, e.g. `app.example.com`. */
	hostname: string,
	/**  Optional path regex, e.g. `^/api`. */
	path: string | null,
	/**  Origin, e.g. `3000` or `http://localhost:3000`. */
	origin: string,
	/**
	 *  Require a login for these people. On an edit, `None` removes the login
	 *  Teitunnel added; on an add, it leaves any existing login alone.
	 */
	access?: AccessRule | null,
};

/**  One route of this Mac's tunnel. */
export type RouteView = {
	/**  Public hostname. */
	hostname: string,
	/**  Path regex. */
	path: string | null,
	/**  Where traffic goes. */
	origin: string,
	/**  Whether the origin is on this Mac. */
	local: boolean,
	/**  The zone (domain) it belongs to. */
	zone: string | null,
	/**  Its DNS record. */
	dns: DnsState,
	/**  Who may reach it, when Teitunnel added a login. */
	access: AccessRule | null,
	/**  What visitors run to reach it, for SSH, RDP, SMB and TCP routes. */
	client: ClientAccess | null,
	/**  The tunnel of this Mac's that carries it. */
	tunnelId: string | null,
	/**  A share on your domain: removed when the share stops. */
	temporary: boolean,
	/**  Load balanced across tunnels (Cloudflare Load Balancing). */
	balanced: boolean,
};

/**  Everything the Routes view shows for an account. */
export type RoutesOverview = {
	/**  This Mac's default tunnel, if it has one. */
	tunnel: TunnelView | null,
	/**  Every tunnel of this Mac's in the account, the default first, then by name. */
	tunnels: TunnelView[],
	/**  Routes, sorted by domain then hostname. */
	routes: RouteView[],
	/**  Domains routes can use. */
	zones: ZoneRef[],
	/**
	 *  Private networks shared through this Mac's tunnel, sorted; `None` when the
	 *  credential can't read them.
	 */
	networks: NetworkView[] | null,
};

/**  One route that differs between what Teitunnel wrote and what's there now. */
export type RuleChange = {
	/**  Hostname. */
	hostname: string,
	/**  Path regex. */
	path: string | null,
	/**  The service Teitunnel wrote (None: added elsewhere). */
	before: string | null,
	/**  The service now (None: removed elsewhere). */
	after: string | null,
};

/**  What a listening process appears to be. */
export type ServiceKind = 
/**  Vite dev server. */
"vite" | 
/**  Next.js. */
"next" | 
/**  Astro. */
"astro" | 
/**  Nuxt. */
"nuxt" | 
/**  Remix / React Router. */
"remix" | 
/**  Django. */
"django" | 
/**  Flask. */
"flask" | 
/**  FastAPI. */
"fastApi" | 
/**  Ruby on Rails. */
"rails" | 
/**  Laravel (`artisan serve`). */
"laravel" | 
/**  Hugo. */
"hugo" | 
/**  Jekyll. */
"jekyll" | 
/**  Another Node.js / Bun / Deno server. */
"node" | 
/**  Python (Django, Flask, FastAPI/uvicorn, http.server…). */
"python" | 
/**  Ruby (Rails, Puma…). */
"ruby" | 
/**  PHP. */
"php" | 
/**  Java / JVM. */
"java" | 
/**  Go. */
"go" | 
/**  A port published by Docker, OrbStack or Colima. */
"docker" | 
/**  A database or cache (not HTTP). */
"database" | 
/**  A macOS system service, e.g. AirPlay Receiver on 5000/7000. */
"system" | 
/**  Anything else. */
"other";

/**  All preferences, with defaults applied. */
export type Settings = {
	/**  Appearance override. */
	theme: Theme,
	/**  Show the Teitunnel icon in the menu bar. */
	showInMenuBar: boolean,
	/**  Notify when this Mac's connector goes down, comes back or crash-loops. */
	notifyConnectors: boolean,
	/**  Notify when a Quick Share goes live or fails. */
	notifyQuickShares: boolean,
	/**  Notify when the Doctor finds a new error. */
	notifyDoctor: boolean,
	/**
	 *  Doctor issues the user chose to ignore (stable issue ids). Changed with
	 *  [`set_ignored`], not through a patch, so concurrent toggles can't lose one.
	 */
	ignoredIssues: string[],
};

/**  A partial update: only the fields that are set change. */
export type SettingsPatch = {
	/**  New appearance override. */
	theme?: Theme | null,
	/**  New menu bar visibility. */
	showInMenuBar?: boolean | null,
	/**  Connector notifications on or off. */
	notifyConnectors?: boolean | null,
	/**  Quick Share notifications on or off. */
	notifyQuickShares?: boolean | null,
	/**  Doctor notifications on or off. */
	notifyDoctor?: boolean | null,
};

/**  How bad an issue is. */
export type Severity = 
/**  Something doesn't work. */
"error" | 
/**  Something may stop working, or needs attention. */
"warning" | 
/**  Worth knowing; nothing is broken. */
"info";

/**  Live traffic numbers for a share. */
export type ShareStats = {
	/**  Requests served. */
	requests: number,
	/**  Requests that failed. */
	errors: number,
};

/**  Where a share is in its life. */
export type ShareStatus = 
/**  cloudflared is starting and asking for a URL. */
{ status: "starting" } | 
/**  The URL works. */
{ status: "live" } | 
/**  Connection lost; cloudflared is reconnecting or restarting. */
{ status: "reconnecting" } | 
/**  It failed and won't recover by itself. */
{ status: "failed"; 
/**  What went wrong, for the user. */
message: Text };

/**  What a step does, for its icon. */
export type StepKind = 
/**  Create the tunnel. */
"createTunnel" | 
/**  Update the tunnel's routes. */
"putConfig" | 
/**  Add a DNS record. */
"createRecord" | 
/**  Repoint a DNS record. */
"updateRecord" | 
/**  Delete a DNS record. */
"deleteRecord" | 
/**  Stop this Mac's connector. */
"stopConnector" | 
/**  Delete the tunnel. */
"deleteTunnel" | 
/**  Add a login method. */
"loginMethod" | 
/**  Create, change or remove a route's login. */
"accessApp" | 
/**  Route or stop routing a private network. */
"networkRoute" | 
/**  Load balance a route, or stop. */
"loadBalancer" | 
/**  Check the route works. */
"verify";

/**  The state of one step while applying. */
export type StepState = 
/**  In progress. */
{ state: "running" } | 
/**  Finished. */
{ state: "done" } | 
/**  Not run by the executor (verification happens afterwards). */
{ state: "skipped" } | 
/**  Failed with a message. */
{ state: "failed"; 
/**  What went wrong. */
message: Text } | 
/**  Being undone after a later step failed. */
{ state: "undoing" } | 
/**  Undone. */
{ state: "undone" } | 
/**  Couldn't be undone; left in place. */
{ state: "undoFailed"; 
/**  What went wrong. */
message: Text };

/**  One step of a plan, as shown in the preview. */
export type StepView = {
	/**  What it does. */
	kind: StepKind,
	/**  One line for the user. */
	description: Text,
	/**  "Copy as command" text, when there's an equivalent command. */
	command: string | null,
};

/**
 *  A message for the user: a catalog key and its arguments.
 * 
 *  Also deserializes from a plain string, shown verbatim: that's how text stored
 *  before messages had keys (activity history) still loads.
 */
export type Text = {
	/**  The catalog key, e.g. `core.doctor.dnsMissing.title`. */
	key: string,
	/**  Values for the message's `{placeholders}`; `count` picks a plural form. */
	args: { [key in string]: Arg },
};

/**  Appearance override. */
export type Theme = 
/**  Follow the system appearance. */
"system" | 
/**  Always light. */
"light" | 
/**  Always dark. */
"dark";

/**  A page of Cloudflare's API token settings. */
export type TokenPage = 
/**  "Create API token" with Teitunnel's permissions pre-selected. */
"create" | 
/**  The list of tokens, to add permissions to an existing one. */
"edit";

/**  Live traffic of one tunnel's connector on this Mac. */
export type Traffic = {
	/**  Samples newer than the read's `since` (all of them without it), oldest first. */
	series: TrafficSeries,
	/**  Requests since the connector started. */
	totalRequests: number,
	/**  Failed requests since the connector started. */
	totalErrors: number,
	/**  Edge connections now. */
	connections: number,
	/**  Round-trip time to the edge now, in milliseconds. */
	rttMs: number | null,
	/**  Edge locations, e.g. `AMS`. */
	locations: string[],
};

/**  Samples as columns: entry `i` of every column belongs to the same interval. */
export type TrafficSeries = {
	/**  End of each interval, in milliseconds since the epoch; ascending. */
	at: number[],
	/**  Seconds each interval covers (rates are counts divided by this). */
	span: number[],
	/**  Requests during the interval. */
	requests: number[],
	/**  Failed requests (the origin couldn't be reached) during the interval. */
	errors: number[],
	/**  1xx and 2xx responses. */
	ok: number[],
	/**  3xx responses. */
	redirects: number[],
	/**  4xx responses. */
	clientErrors: number[],
	/**  5xx responses. */
	serverErrors: number[],
	/**  Most requests in flight at once (at the sample; the peak for rollups). */
	concurrent: number[],
	/**  Edge connections (at the sample; the lowest for rollups). */
	connections: number[],
	/**  Smoothed round trip to the edge, in milliseconds (the mean for rollups). */
	rttMs: (number | null)[],
};

/**  A tunnel in the account. */
export type TunnelSummary = {
	/**  Tunnel id. */
	id: string,
	/**  Name. */
	name: string,
	/**  Cloudflare's status: `inactive`, `degraded`, `healthy` or `down`. */
	status: string,
	/**  Created (RFC 3339). */
	createdAt: string,
	/**  Routes in its remote configuration (None: configured locally, or unreadable). */
	routes: number | null,
	/**  Machines running it. */
	connectors: ConnectorView[],
	/**  One of this Mac's tunnels (created and run by Teitunnel here). */
	thisMac: boolean,
	/**  This Mac's default tunnel (where new routes go unless another is chosen). */
	isDefault: boolean,
	/**  Connector state on this Mac, for this Mac's tunnel. */
	connector: ConnectorState | null,
};

/**  This Mac's tunnel. */
export type TunnelView = {
	/**  Tunnel id. */
	id: string,
	/**  Name. */
	name: string,
	/**  Connector state on this Mac (`None`: not running). */
	connector: ConnectorState | null,
	/**  The machine tunnel: where routes go unless another is chosen. */
	isDefault: boolean,
};

/**  Whether a newer cloudflared is available. */
export type UpdateInfo = {
	/**  Latest published version. */
	latest: string,
	/**  Whether it's newer than the one in use (or none is installed). */
	available: boolean,
};

/**  The result of checking one hostname. */
export type Verification = {
	/**  Hostname. */
	hostname: string,
	/**  The origin's HTTP status, when it answered. */
	status: number | null,
	/**  What's wrong, if anything. */
	failure: Failure | null,
	/**  The failure, in a sentence for the UI. */
	message: Text | null,
	/**
	 *  Cloudflare asked for a login (Access) instead of passing the request on, so the
	 *  check reached the edge but not the origin behind the login.
	 */
	protected: boolean,
};

/**  Something the user should know before applying. */
export type Warning = 
/**  Only one tunnel serves the hostname: there's nothing to fail over to yet. */
{ type: "singleEndpoint"; 
/**  Hostname. */
hostname: string } | 
/**  A record Teitunnel didn't create will be replaced. */
{ type: "replacesForeignRecord"; 
/**  Hostname. */
hostname: string; 
/**  Existing type. */
kind: string; 
/**  Existing content. */
content: string } | 
/**  A record Teitunnel didn't create will be deleted. */
{ type: "deletesForeignRecord"; 
/**  Hostname. */
hostname: string; 
/**  Type. */
kind: string; 
/**  Content. */
content: string } | 
/**  A record Teitunnel didn't create is left in place. */
{ type: "keepsForeignRecord"; 
/**  Hostname. */
hostname: string } | 
/**  No routes are left on the tunnel. */
{ type: "tunnelEmpty" } | 
/**  The origin isn't on this Mac, so it must be reachable from here. */
{ type: "remoteOrigin"; 
/**  The origin. */
origin: string } | 
/**
 *  The range isn't private address space: WARP clients would send traffic for those
 *  public addresses to this Mac instead of the internet.
 */
{ type: "publicNetwork"; 
/**  The range. */
network: string } | 
/**
 *  Part of the range is already routed to another tunnel; the more specific route
 *  wins for the addresses both cover.
 */
{ type: "overlapsNetwork"; 
/**  The range being added. */
network: string; 
/**  The other route's range. */
other: string; 
/**  The other route's tunnel. */
tunnel: string };

/**  DNS permission for one domain. */
export type ZoneGrant = {
	/**  Zone id. */
	zoneId: string,
	/**  Domain name. */
	zoneName: string,
	/**  Whether DNS records can be edited. */
	dnsEdit: Grant,
};

/**  A zone the account can use. */
export type ZoneRef = {
	/**  Zone id. */
	id: string,
	/**  Apex name. */
	name: string,
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

